usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.FineTuning.Alpha.Graders.Run.New(
		context.TODO(),
		openai.FineTuningAlphaGraderRunNewParams{
			Grader: openai.GraderStringCheck{Type: "string_check", Name: "string", Input: "string", Reference: "string", Operation: openai.GraderStringCheckOperationEq},
			Item: map[string]any{"key": nil},
			ModelSample: "string",
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
